#include <sqlite3.h>
#include <filesystem>
#include <iostream>
#include <stdexcept>
#include <string>
#include <vector>
#include <cstring>
namespace fs=std::filesystem;
void require(bool ok,const char* message){if(!ok)throw std::runtime_error(message);}
struct Query{sqlite3_stmt* q=nullptr;Query(sqlite3* db,const std::string& sql){require(sqlite3_prepare_v2(db,sql.c_str(),-1,&q,nullptr)==SQLITE_OK,"Query prepare failed");}~Query(){sqlite3_finalize(q);}bool next(){const auto rc=sqlite3_step(q);require(rc==SQLITE_ROW||rc==SQLITE_DONE,"Query failed");return rc==SQLITE_ROW;}std::string text(int col){const auto* p=sqlite3_column_text(q,col);return p?std::string(reinterpret_cast<const char*>(p),sqlite3_column_bytes(q,col)):"";}};
void exec(sqlite3* db,const char* sql){require(sqlite3_exec(db,sql,nullptr,nullptr,nullptr)==SQLITE_OK,"SQL operation failed");}
long long scalar(sqlite3* db,const char* sql){Query q(db,sql);require(q.next(),"Missing scalar");return sqlite3_column_int64(q.q,0);}
struct Database{sqlite3* db=nullptr;Database(const fs::path& path,bool readonly=false){require(sqlite3_open_v2(path.c_str(),&db,readonly?SQLITE_OPEN_READONLY:SQLITE_OPEN_READWRITE|SQLITE_OPEN_CREATE,nullptr)==SQLITE_OK,"Open failed");require(sqlite3_key(db,"synthetic-storage-comparison",28)==SQLITE_OK,"Key failed");exec(db,"PRAGMA cipher_compatibility=4; PRAGMA cipher_memory_security=ON; PRAGMA cache_size=-32768; PRAGMA journal_mode=DELETE; PRAGMA synchronous=EXTRA; PRAGMA fullfsync=ON; PRAGMA foreign_keys=ON; PRAGMA temp_store=MEMORY; PRAGMA secure_delete=ON");}~Database(){sqlite3_close(db);}};
void check(sqlite3* db){Query integrity(db,"PRAGMA integrity_check");require(integrity.next()&&integrity.text(0)=="ok"&&!integrity.next(),"Integrity check failed");Query cipher(db,"PRAGMA cipher_integrity_check");require(!cipher.next(),"Cipher integrity check failed");Query fk(db,"PRAGMA foreign_key_check");require(!fk.next(),"Foreign key check failed");}
std::string quote(const std::string& name){std::string s="\"";for(char c:name){s+=c;if(c=='\"')s+=c;}return s+'"';}
bool same_value(sqlite3_stmt* a,sqlite3_stmt* b,int i){const int t=sqlite3_column_type(a,i);if(t!=sqlite3_column_type(b,i))return false;if(t==SQLITE_NULL)return true;if(t==SQLITE_INTEGER)return sqlite3_column_int64(a,i)==sqlite3_column_int64(b,i);if(t==SQLITE_FLOAT){const double x=sqlite3_column_double(a,i),y=sqlite3_column_double(b,i);return std::memcmp(&x,&y,sizeof x)==0;}const int n=sqlite3_column_bytes(a,i);return n==sqlite3_column_bytes(b,i)&&(n==0||std::memcmp(sqlite3_column_blob(a,i),sqlite3_column_blob(b,i),n)==0);}
long long equal_query(sqlite3* a,sqlite3* b,const std::string& sql){Query x(a,sql),y(b,sql);long long rows=0;for(;;){const bool ax=x.next(),by=y.next();require(ax==by,"Logical row count mismatch");if(!ax)break;require(sqlite3_column_count(x.q)==sqlite3_column_count(y.q),"Column mismatch");for(int i=0;i<sqlite3_column_count(x.q);++i)require(same_value(x.q,y.q,i),"Typed logical value mismatch");++rows;}return rows;}
void equality(sqlite3* a,sqlite3* b){equal_query(a,b,"SELECT type,name,tbl_name,sql FROM sqlite_schema ORDER BY type,name");Query tables(a,"SELECT name,sql FROM sqlite_schema WHERE type='table' ORDER BY name");int count=0;long long rows=0;while(tables.next()){const auto name=tables.text(0);const bool rowid=tables.text(1).find("WITHOUT ROWID")==std::string::npos;std::string columns=rowid?"rowid":"",order=rowid?"rowid":"";Query fields(a,"PRAGMA table_info("+quote(name)+")");while(fields.next()){if(!columns.empty()){columns+=',';order+=',';}columns+=quote(fields.text(1));order+=quote(fields.text(1));}rows+=equal_query(a,b,"SELECT "+columns+" FROM "+quote(name)+" ORDER BY "+order);++count;}std::cout<<"logical_equality,tables="<<count<<",rows="<<rows<<",typed_values=equal,implicit_rowids=equal,schema=equal\n";for(const auto* pragma:{"PRAGMA user_version","PRAGMA application_id"})require(scalar(a,pragma)==scalar(b,pragma),"Document identity changed");}
void metrics(sqlite3* db,const fs::path& p,const char* phase){const auto size=scalar(db,"PRAGMA page_size"),pages=scalar(db,"PRAGMA page_count"),free=scalar(db,"PRAGMA freelist_count");std::cout<<"metrics,"<<phase<<",file_bytes="<<fs::file_size(p)<<",page_size="<<size<<",pages="<<pages<<",freelist_pages="<<free<<",live_page_bytes="<<(pages-free)*size<<'\n';}
void protected_file(const fs::path& path){for(bool wrong:{false,true}){sqlite3* db=nullptr;require(sqlite3_open_v2(path.c_str(),&db,SQLITE_OPEN_READONLY,nullptr)==SQLITE_OK,"Protection open failed");if(wrong)sqlite3_key(db,"incorrect",9);sqlite3_stmt* q=nullptr;const int prepared=sqlite3_prepare_v2(db,"SELECT count(*) FROM sqlite_schema",-1,&q,nullptr);int rc=prepared;if(prepared==SQLITE_OK)rc=sqlite3_step(q);sqlite3_finalize(q);sqlite3_close(db);require(rc==SQLITE_NOTADB,"Unkeyed/wrong-key access was not refused");}std::cout<<"protection,unkeyed=refused,wrong_key=refused\n";}
int main(int argc,char** argv){try{require(argc==3,"Usage: probe closed-synthetic-source fresh-output-directory");const fs::path source=argv[1],root=argv[2];require(!fs::exists(root),"Refusing existing output directory");fs::create_directories(root);const auto compact=root/"vacuum.spentit",backup=root/"backup.spentit";fs::copy_file(source,compact);Database original(source,true);check(original.db);metrics(original.db,source,"original");std::cout<<"sqlite,"<<sqlite3_libversion()<<'\n';Query version(original.db,"PRAGMA cipher_version");require(version.next(),"SQLCipher unavailable");std::cout<<"sqlcipher,"<<version.text(0)<<'\n';
{Database copy(compact);check(copy.db);equality(original.db,copy.db);exec(copy.db,"VACUUM");check(copy.db);equality(original.db,copy.db);metrics(copy.db,compact,"vacuum");}
{Database restored(compact,true);check(restored.db);equality(original.db,restored.db);}protected_file(compact);
{Database target(backup);sqlite3_backup* b=sqlite3_backup_init(target.db,"main",original.db,"main");require(b,"Backup initialization failed");int rc=SQLITE_OK;do{rc=sqlite3_backup_step(b,128);}while(rc==SQLITE_OK);const int done=sqlite3_backup_finish(b);require(rc==SQLITE_DONE&&done==SQLITE_OK,"Backup failed");check(target.db);equality(original.db,target.db);metrics(target.db,backup,"backup");}
{Database restored(backup,true);check(restored.db);equality(original.db,restored.db);}protected_file(backup);std::cout<<"checks,integrity=ok,cipher_integrity=ok,foreign_keys=ok,reopen=ok\n";return 0;
}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
